// Normalise one Calendly invitee.created payload into the fields the rest of
// the workflow uses. Calendly nests the invitee under payload; older webhook
// versions put it at the root, so accept both.
const p = $json.payload ?? $json;

const email = String(p.email ?? '').trim().toLowerCase();
if (!email) {
  throw new Error('Calendly payload had no invitee email — cannot resolve a Pipedrive person.');
}

const fullName = String(p.name ?? '').trim();
const parts = fullName.split(/\s+/).filter(Boolean);
const firstName = parts[0] ?? '';
const lastName = parts.slice(1).join(' ');

const domain = email.split('@')[1] ?? '';

// Free-mail domains must never become a Pipedrive Organization, and must never
// be added to the Smartlead block list — blocking gmail.com would silence every
// future campaign. Treated as "no company" throughout.
const FREE_MAIL = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
  'live.com', 'aol.com', 'icloud.com', 'me.com', 'proton.me', 'protonmail.com',
  'gmx.com', 'mail.com', 'yandex.com', 'zoho.com', 'msn.com',
]);
const isFreeMail = FREE_MAIL.has(domain);

// Calendly sends the company name only when the booking form asks for it.
let company = '';
for (const q of p.questions_and_answers ?? []) {
  if (/company|organi[sz]ation|business/i.test(q.question ?? '')) {
    company = String(q.answer ?? '').trim();
    break;
  }
}
if (!company && !isFreeMail && domain) {
  company = domain.split('.')[0].replace(/[-_]/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

const ev = p.scheduled_event ?? {};
const startsAt = ev.start_time ?? p.start_time ?? null;

// Pipedrive activity wants due_date (YYYY-MM-DD) and due_time (HH:MM) in UTC.
let dueDate = '';
let dueTime = '';
if (startsAt) {
  const d = new Date(startsAt);
  dueDate = d.toISOString().slice(0, 10);
  dueTime = d.toISOString().slice(11, 16);
}

return {
  json: {
    email,
    fullName: fullName || email,
    firstName,
    lastName,
    domain,
    isFreeMail,
    company,
    hasCompany: Boolean(company) && !isFreeMail,
    startsAt,
    dueDate,
    dueTime,
    eventName: ev.name ?? 'Meeting',
    reschedule: Boolean(p.rescheduled),
    cancelUrl: p.cancel_url ?? '',
  },
};

// Carry the booking fields forward alongside whatever the person search found.
// Everything downstream reads from this single flat shape.
const booking = $('Normalize Booking').item.json;
const hit = $json?.data?.items?.[0]?.item ?? null;

return {
  json: {
    ...booking,
    personId: hit?.id ?? null,
    personFound: Boolean(hit),
    // A person already in Pipedrive usually carries their organisation.
    orgId: hit?.organization?.id ?? null,
  },
};

const booking = $('Resolve Person').item.json;
const hit = $json?.data?.items?.[0]?.item ?? null;

return {
  json: {
    ...booking,
    orgId: hit?.id ?? null,
    orgFound: Boolean(hit),
  },
};

// Reached from three paths: org just created, org already existed, or the
// booking had no usable company at all. Normalise them to one shape.
const prev = $('Resolve Person').item.json;

// When this item came through Create Organization the new id is on $json.data.
const createdOrgId = $json?.data?.id ?? null;

// When it came through Resolve Org (existing org) the id is already on $json.
const carriedOrgId = $json?.orgId ?? null;

return {
  json: {
    ...prev,
    ...(typeof $json.company === 'string' ? { company: $json.company } : {}),
    orgId: createdOrgId ?? carriedOrgId ?? prev.orgId ?? null,
  },
};

// Single join point for both branches: person already existed, or was just
// created. After this node every item has a real personId.
const prev = $('Resolve Person').item.json;

const createdPersonId = $json?.data?.id ?? null;
const createdOrgId = $json?.data?.org_id?.value ?? $json?.orgId ?? null;

const personId = createdPersonId ?? prev.personId ?? null;
if (!personId) {
  throw new Error(`No Pipedrive person could be resolved or created for ${prev.email}`);
}

return {
  json: {
    ...prev,
    personId,
    orgId: createdOrgId ?? prev.orgId ?? null,
  },
};

// One flat row per booking, matching the calendly-log sheet header.
const b = $('Person Ready').item.json;

return {
  json: {
    timestamp: new Date().toISOString(),
    lead_name: b.fullName,
    lead_email: b.email,
    company: b.company || '',
    event_name: b.eventName,
    starts_at: b.startsAt || '',
    person_id: b.personId,
    org_id: b.orgId || '',
    lead_id: $('Create Lead').item.json?.data?.id ?? '',
    domain_blocked: b.isFreeMail ? 'no (free mail)' : 'yes',
    is_reschedule: b.reschedule ? 'yes' : 'no',
  },
};
